export const STORY_FORGE_SUPPLEMENT_CASES=Object.freeze(CASES.map(c=>({id:c.id,requirements:c.requirements,long:!!c.long,touch:!!c.touch,reduced:!!c.reduced})));
/** Caller owns the page/context. Every case is a fresh real URL navigation.
 * Touch case needs a context with hasTouch:true. Natural images are opt-in.
 */
export async function runStoryForgeSupplement(page,options={}){
 if(!options.url||!options.reportPath||!options.expectedDocumentSha256)throw Error('url, reportPath and expectedDocumentSha256 are required');const url=new URL(options.url);if(!['http:','https:'].includes(url.protocol))throw Error('Owned HTTP(S) URL required');
 const matrix=selections(options),names=matrix.cases,selected=CASES.filter(c=>names.includes(c.id));if(selected.some(c=>c.long)&&!options.includePlayback)throw Error('Natural images require --include-playback');
 const themes=matrix.themes,languages=matrix.languages,viewport=options.viewport||{width:1440,height:900};const dir=options.artifactDir||path.join(path.dirname(path.resolve(options.reportPath)),path.basename(options.reportPath,'.json')+'-cases');await mkdir(dir,{recursive:true});
 const report={kind:'Story Forge supplementary raw acceptance evidence',startedAt:new Date().toISOString(),url:options.url,expectedDocumentSha256:options.expectedDocumentSha256,themes,languages,viewport,selectedCases:names,caseContract:STORY_FORGE_SUPPLEMENT_CASES,cases:[],fatal:null,limits:['Finite native Chromium input/RAF observations; not universal hardware/browser proof.','A11 actual images use computed URL hashes, model slot identity, visibility/hit test and stable DOM handle; not dataset-only.','Only Story Forge portions of global/other-section acceptance run here; old prototype/hover method is superseded.','Natural sampling/RAF timing are measured, never faked. A bounded observation ending is not target failure.','Parent owns all A7/section/whole-goal acceptance and paired physical-state review.']};
 const persist=()=>writeFile(options.reportPath,JSON.stringify(report,null,2)+'\n');const consoleErrors=[];let active=null;const onError=e=>consoleErrors.push({case:active,type:'pageerror',error:errorText(e)}),onConsole=m=>{if(m.type()==='error')consoleErrors.push({case:active,type:'console',error:m.text()});};page.on('pageerror',onError);page.on('console',onConsole);
 try{for(const theme of themes)for(const lang of languages)for(const definition of selected){active=`${theme}-${lang}-${viewport.width}-${definition.id}`;const result={key:active,id:definition.id,theme,language:lang,viewport,startedAt:new Date().toISOString(),requirements:definition.requirements,checks:[],evidence:{},errors:[],unverified:[],screenshots:[]},startErrors=consoleErrors.length;let reader;
 try{await page.setViewportSize(viewport);await page.emulateMedia({reducedMotion:definition.reduced?'reduce':'no-preference'});await page.goto('about:blank');const target=new URL(options.url);target.hash=`scheme=${theme}&lang=${lang}`;const response=await page.goto(target.href,{waitUntil:'domcontentloaded',timeout:20000});const doc=response?{url:response.url(),status:response.status(),sha256:createHash('sha256').update(await response.body()).digest('hex')}:null;result.evidence.document=doc;if(doc?.sha256!==options.expectedDocumentSha256)throw Error('Document identity drift: '+JSON.stringify(doc));await page.waitForSelector('#sf-cvInner .ci',{timeout:20000});await page.locator('#sf').scrollIntoViewIfNeeded();await wait(page);reader=await measurement(page);
 const c={page,reader,document:doc,evidence:result.evidence,unverified:result.unverified,read:()=>reader.evaluate(fn=>fn()),check:(id,pass,observation)=>result.checks.push({id,pass:!!pass,observation}),capture:async label=>{const file=path.join(dir,active+'-'+label+'.png');await page.screenshot({path:file});result.screenshots.push({label,path:file});}};result.evidence.entry=await c.read();c.check('entry.correct-theme-language',result.evidence.entry.scheme===theme&&result.evidence.entry.language===lang,{theme,lang,actualScheme:result.evidence.entry.scheme,actualLanguage:result.evidence.entry.language});await definition.run(c);
 }catch(e){result.errors.push({type:'action-or-observation-error',error:errorText(e)});}finally{try{await page.mouse.up();await page.keyboard.up('Control');await page.keyboard.press('Escape');}catch{}await reader?.dispose();}
 result.errors.push(...consoleErrors.slice(startErrors));result.finishedAt=new Date().toISOString();result.status=result.errors.length||result.unverified.length?'unverified':result.checks.some(c=>!c.pass)?'not attained':'attained';const file=path.join(dir,active+'.json');await writeFile(file,JSON.stringify(result,null,2)+'\n');result.artifact=file;report.cases.push(result);report.summary={cases:report.cases.length,attained:report.cases.filter(c=>c.status==='attained').length,notAttained:report.cases.filter(c=>c.status==='not attained').length,unverified:report.cases.filter(c=>c.status==='unverified').length,checks:report.cases.reduce((n,c)=>n+c.checks.length,0),passed:report.cases.reduce((n,c)=>n+c.checks.filter(c=>c.pass).length,0)};await persist();console.log(JSON.stringify({case:active,status:result.status,checks:result.checks.length,failed:result.checks.filter(c=>!c.pass).map(c=>c.id),errors:result.errors.length}));}
 }catch(e){report.fatal=errorText(e);}finally{page.off('pageerror',onError);page.off('console',onConsole);report.finishedAt=new Date().toISOString();report.allSelectedChecksPass=!report.fatal&&selected.length>0&&themes.length>0&&languages.length>0&&report.cases.length>0&&report.cases.length===themes.length*languages.length*selected.length&&report.cases.every(c=>c.status==='attained');await persist();}return report;
}
function argsParse(a){const o={};for(let i=0;i<a.length;i++){const k=a[i];if(['--include-playback','--touch','--help'].includes(k))o[k.slice(2)]=true;else if(['--url','--report','--cases','--themes','--languages','--viewport','--chrome','--expected-document-sha256'].includes(k)){if(!a[i+1])throw Error('Missing '+k);o[k.slice(2)]=a[++i];}else throw Error('Unknown '+k);}return o;}
async function cli(){const a=argsParse(process.argv.slice(2));if(a.help){console.log('node parity/story-forge-supplement.mjs --url URL --report PATH --expected-document-sha256 HASH [--cases '+CASES.map(c=>c.id).join(',')+'] [--themes pure,neon] [--languages zh,en] [--viewport 1440x900] [--touch] [--include-playback]');return;}if(!a.url||!a.report||!a['expected-document-sha256'])throw Error('--url --report --expected-document-sha256 required');const matrix=selections({cases:a.cases,themes:a.themes,languages:a.languages});if(matrix.cases.includes('natural-images')&&!a['include-playback'])throw Error('Natural images require --include-playback');const chrome=await requireBrowser(a.chrome);await stat(chrome);const size=(a.viewport||'1440x900').split('x').map(Number);if(size.length!==2||size.some(x=>!Number.isFinite(x)||x<1))throw Error('Invalid viewport');let browser;
 try{browser=await chromium.launch({headless:true,executablePath:chrome,args:['--no-sandbox']});const context=await browser.newContext({viewport:{width:size[0],height:size[1]},hasTouch:!!a.touch}),page=await context.newPage();const report=await runStoryForgeSupplement(page,{url:a.url,reportPath:a.report,cases:matrix.cases,themes:matrix.themes,languages:matrix.languages,viewport:{width:size[0],height:size[1]},expectedDocumentSha256:a['expected-document-sha256'],includePlayback:!!a['include-playback']});report.environment={node:process.version,chrome,browserVersion:browser.version(),runnerSha256:createHash('sha256').update(await readFile(fileURLToPath(import.meta.url))).digest('hex'),hasTouch:!!a.touch};await writeFile(a.report,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({report:path.resolve(a.report),summary:report.summary,fatal:report.fatal}));if(!report.allSelectedChecksPass)process.exitCode=1;await context.close();}finally{await browser?.close();}}
if(process.argv[1]&&pathToFileURL(path.resolve(process.argv[1])).href===import.meta.url)cli().catch(e=>{console.error(errorText(e));process.exitCode=1;});
